#include <map>
#include <string>
#include <vector>

using Data = std::map<std::string, std::string>;
struct Mod { std::string name; Data entries; };
struct Merged { Data values; std::map<std::string, std::string> source; std::vector<std::string> conflicts; };

Merged mergeData(const Data& base, const std::vector<Mod>& mods)
{
    Merged m;
    for (const auto& [key, value] : base) { m.values[key] = value; m.source[key] = "base"; }
    std::map<std::string, int> setBy;                    // key -> how many mods set it
    for (const Mod& mod : mods)
    {
        for (const auto& [key, value] : mod.entries)
        {
            m.values[key] = value;
            m.source[key] = mod.name;
            ++setBy[key];
        }
    }
    for (const auto& [key, count] : setBy)               // std::map: already alphabetical
        if (count >= 2) m.conflicts.push_back(key);
    return m;
}

unitTests:
const Data base{ { "troll.health", "120" }, { "goblin.damage", "4" } };
TEST("the example")
{
    const Merged m{ mergeData(base, { { "tougher-trolls", { { "troll.health", "200" } } }, { "easy-mode", { { "goblin.damage", "2" }, { "troll.health", "90" } } } }) };
    CHECK_EQ(m.values.at("troll.health"), std::string("90"));
    CHECK_EQ(m.source.at("troll.health"), std::string("easy-mode"));
    CHECK_EQ(m.values.at("goblin.damage"), std::string("2"));
    CHECK(m.conflicts == std::vector<std::string>({ "troll.health" }));
}
TEST("independent mods both apply") { const Merged m{ mergeData(base, { { "a", { { "troll.health", "200" } } }, { "b", { { "goblin.damage", "1" } } } }) }; CHECK_EQ(m.values.at("troll.health"), std::string("200")); CHECK_EQ(m.values.at("goblin.damage"), std::string("1")); CHECK(m.conflicts.empty()); }
TEST("untouched keys come from the base") { const Merged m{ mergeData(base, {}) }; CHECK_EQ(m.source.at("goblin.damage"), std::string("base")); }
TEST("mods can add new keys") { const Merged m{ mergeData(base, { { "new-monster", { { "wraith.health", "70" } } } }) }; CHECK_EQ(m.values.at("wraith.health"), std::string("70")); CHECK_EQ(m.source.at("wraith.health"), std::string("new-monster")); }
TEST("conflicts are sorted") { const Merged m{ mergeData({}, { { "a", { { "z.k", "1" }, { "b.k", "1" } } }, { "b", { { "z.k", "2" }, { "b.k", "2" } } } }) }; CHECK(m.conflicts == std::vector<std::string>({ "b.k", "z.k" })); }

